-- Average units per order | postgres
-- Generated by scripts/export-demo-sql.ts; display formatting only.
-- Ordered sample parameters: [0]
-- r4 aggregate: merged; Compatible row-level input block
-- r1 project: merged; Compatible row-level input block
-- r0 aggregate: merged; Compatible row-level input block
select
  cast(
    avg(
      cast(
        coalesce("r6"."c1", cast($1 as double precision)) as double precision
      )
    ) as double precision
  ) as "average_units"
from
  "orders" as "r2"
  left join (
    select
      "order_details"."order_id" as "c0",
      cast(
        sum(
          cast("order_details"."quantity" as double precision)
        ) as double precision
      ) as "c1"
    from
      "order_details"
    group by
      "order_details"."order_id"
  ) as "r6" on ("r2"."order_id" = "r6"."c0");
